(window.__BOOKS=window.__BOOKS||{})["e_cyclops"]={"b":[["lead","Драма сатиров"],["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"silen\">Силен</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор сатиров</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"odissey\">Одиссей</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"kiklop\">Киклоп</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Статисты: спутники <span class=\"ch\" data-ch=\"odissey\">Одиссея</span> и рабы <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>.</span>"],["act","Пролог","a1",""],["sd","Сцена представляет берег моря и в некотором отдалении от него скат Этны и вход в пещеру, перед которым загорода и лужайка. Загорода протянута между двумя выступами скал. На лужайке приготовлены ведра с водой. Вокруг дикая утесистая местность. Начало действия около полудня."],["scene","Явление первое","s1",1,1],["sd","Из пещеры выходит старый <span class=\"ch\" data-ch=\"silen\">Силен</span> с железными граблями в руках."],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Сочту ли я, о Бромий, те труды,",0,1,0,0],["v","Которые от юности доныне",0,1,0,0],["v","Из-за тебя мы терпим? Начались",0,1,0,0],["v","С тех пор они, как ты, безумьем Геры",0,1,0,0],["v","Охваченный, ушел от Ореад",0,2,0,0],["v","И их дозора, Бромий. Позже я",0,3,0,0],["v","Щит по следам носил твоим в сраженье<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,4,0,0],["v","С рожденными Землею. Энкеладу<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,5,0,0],["v","Пробив броню, гиганта уложил",0,6,0,0],["v","Ударом я в той битве… Так ли, полно?",0,7,0,0],["v","Уж не во сне ль я видел? Нет, доспех",0,8,0,0],["v","Я показал тогда же Вакху. Были",0,9,0,0],["v","Труды, но то, что терпим ныне, горше.",0,10,0,1],["sd","(Помолчав.)"],["v","Когда, тебе судив далекий путь,",0,11,0,0],["v","Разбойников подустила тирренских",0,12,0,0],["v","Кронидова жена и эта весть",0,13,0,0],["v","Дошла до нас, я сыновей на розыск",0,14,0,0],["v","Повез. На руль, конечно, сам, они ж",0,15,0,0],["v","На весла налегают и лазурь",0,16,0,0],["v","Ударами их бороздят и пенят.",0,17,0,0],["v","И были мы уж у Малеи — вдруг<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,18,0,0],["v","С востока нас подхватывает ветер",0,19,0,0],["v","И на утес бросает этот, где",0,20,0,1],["v","Царя морского дети, одноглазый<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,20,0,0],["v","Свирепый род ютится по пещерам.",0,21,0,0],["v","Киклопами зовут их… К одному",0,22,0,0],["v","Из них — увы! — рабами мы попали.",0,23,0,0],["v","Он Полифем по имени, и нет",0,24,0,0],["v","Для нас в его пещере ликований",0,25,0,0],["v","Вакхических; безбожному стада",0,25,0,0],["v","<span class=\"ch\" data-ch=\"kiklop\">Киклопу</span> мы пасем. По скалам дальним",0,26,0,0],["v","Моих детей их молодые ноги",0,27,0,0],["v","За козами гоняют — я ж смотрю,",0,28,0,0],["v","Чтоб молока довольно было в ведрах,",0,29,0,0],["v","Да этот дом для нечестивца мне",0,30,0,1],["v","Приказано держать в порядке. Должен",0,30,0,0],["v","И за столом служить я. Вот теперь",0,31,0,0],["v","Ты хочешь иль не хочешь, а скребницей",0,32,0,0],["v","Железною работай, — чистоту",0,33,0,0],["v","Стада и господин наш, видишь, любит.",0,34,0,0],["sd","С домашней стороны на орхестру спускается хор молодых сатиров — это еще полудети. Они гонят стадо, с которым им довольно трудно справиться, потому что они увлечены пляской, поддерживая ее музыкой импровизированных кастаньет и подражанием звукам бубна и рожка."],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","еще не видя их"],["v","Но что я слышу? Будто плясовой",0,35,0,0],["v","Несется лад и музыка… Ну право ж,",0,36,0,0],["v","Как в те часы, когда, ликуя, хором",0,37,0,0],["v","Вы, Сатиры, к Алфее провожали",0,38,0,0],["sd","(он увидел сыновей)"],["v","Гремучего, и лиры опьянял<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,39,0,0],["v","Вас нежный стон, божественная свита.",0,40,0,1],["scene","Явление второе","s2",1,2],["sd","<span class=\"ch\" data-ch=\"silen\">Силен</span> и хор."],["scene","Вступительная песнь хора","s3",1,3],["sd","в сопровождении мимической сцены, которая заключается в том, что сатиры стараются загнать стадо в загороду, а оттуда в пещеру."],["sp","Хор"],["str","Строфа"],["v","Славная родом, куда ты,",0,40,0,0],["v","Матери славной дочь?",0,41,0,0],["v","Что ты? Опять на скале?",0,42,0,0],["v","Здесь-то — ветер какой",0,43,0,0],["v","Теплый, трава какая,",0,44,0,0],["v","Прямо из речки вода…",0,45,0,0],["v","В ведрах, гляди, кружится!",0,45,0,0],["v","Вот и наш дом… А там,",0,46,0,0],["v","Слышишь, ягнята плачут…",0,47,0,0],["str","Месод"],["v","Ты, кому говорим мы, разве ж",0,48,0,0],["v","Плохо тебе гулять",0,49,0,0],["v","Здесь по траве росистой?",0,50,0,1],["v","Гей, круторогий, куда",0,51,0,0],["v","Стадо ведешь? Дождешься",0,52,0,0],["v","Камня в широкий лоб…",0,53,0,0],["str","Антистрофа"],["v","Что молока-то скопилось!",0,54,0,0],["v","Время детей кормить…",0,55,0,0],["v","Дай же сосцы им!.. Пора, ведь",0,56,0,0],["v","Бедные целый день",0,57,0,0],["v","Спали голодные: слышишь,",0,58,0,0],["v","Ищут тебя, зовут…",0,59,0,0],["v","Долго ль еще ты будешь",0,60,0,1],["v","Травы мять на лугу?",0,61,0,0],["v","Гей ты!.. Сейчас в пещеру!..",0,62,0,0],["str","Эпод"],["v","Нет для нас Бромия больше,",0,63,0,0],["v","С тирсами нет менад,",0,64,0,0],["v","Гула отрадного бубна,",0,65,0,0],["v","Тонкой струи вина",0,66,0,0],["v","Над серебром потоков,",0,67,0,0],["v","Танца безумных нимф…",0,68,0,0],["v","Песнью лилась там радость,",0,70,0,1],["v","Дивный напев ее звал,",0,70,0,0],["v","Ту, которую выбрал",0,71,0,0],["v","Я среди белоногих,",0,72,0,0],["v","Быстрых ее подруг.",0,72,0,0],["v","О Дионис, о Бромий,",0,73,0,0],["v","Где ты один? И ветер",0,74,0,0],["v","Какой твоею играет,",0,75,0,0],["v","О бог, золотою гривой?",0,75,0,0],["v","А над твоим слугою",0,76,0,0],["v","Другой господин; один лишь",0,77,0,0],["v","Глаз у <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>, Бромий.",0,77,0,0],["v","Бродит слуга печальный",0,78,0,0],["v","В этом жалком отребье",0,79,0,0],["v","Шкуры козьей и светлых",0,80,0,1],["v","Глаз твоих, боже, не видит.",0,81,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","видя, что сатиры, размечтавшись, опять забыли о стаде, которое разбредается, хлопая в ладоши, вызывает рабов"],["v","Довольно, дети, слугам в эту сень",0,82,0,0],["v","Глубокую загнать велите стадо.",0,83,0,0],["sd","Сатиры, обрадованные отдыхом, разлеглись, пока рабы загоняют стадо."],["sp","Хор"],["dir","к рабам, которые уже делают за них привычную работу"],["v","Гей!.. вы… Но сам родитель впопыхах?..",0,84,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","У берега я вижу корпус судна",0,85,0,0],["v","Аргосского, гребцов и их вождя.",0,86,0,0],["v","Они идут к пещере, а на шеях",0,87,0,0],["v","Повешены корзины, и пустые,",0,88,0,0],["v","Должно быть, за припасом, да кувшины",0,89,0,0],["v","Чтоб их водой наполнить… Бедняки,",0,90,0,1],["v","Откуда-то они?.. Им неизвестен,",0,90,0,0],["v","Конечно, нрав <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span> и его",0,91,0,0],["v","Неласковый приют; они не знают,",0,92,0,0],["v","Что челюсти здесь жадные их ждут.",0,92,0,0],["v","Однако не шумите… Мы узнаем,",0,93,0,0],["v","В Сицилию они попали как,",0,94,0,0],["v","Сюда, к подошве Этны… Тише, дети.",0,95,0,0],["act","Действие первое","a2","I"],["scene","Явление третье","s4",2,4],["sd","Те же и <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> со свитой (с внешней стороны). У них вид морских скитальцев, загоревших, оборванных и обветренных. У матросов корзины и кувшины, у <span class=\"ch\" data-ch=\"odissey\">Одиссея</span> под перекидкой длинный меч, а за спиной мех с вином с привязанной к нему чашей."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","замечая сначала рабов с ведрами воды"],["v","Скажите-ка, почтенные, воды",0,95,0,0],["v","Поблизости найдем ли мы напиться",0,96,0,0],["v","Проточной и припасов кто-нибудь",0,97,0,0],["v","Голодным не продаст ли мореходам?",0,97,0,0],["v","(Заметив сатиров и <span class=\"ch\" data-ch=\"silen\">Силена</span>.)",0,98,0,0],["v","Ба… ба… Что вижу я? Уж этот край",0,99,0,0],["v","Не Вакху ль посвящен? Толпа сатиров…",0,100,0,1],["v","Старейшему из них сперва привет.",0,101,0,0],["sd","(Кланяется <span class=\"ch\" data-ch=\"silen\">Силену</span>.)"],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","отдавая поклон"],["v","И наш тебе… Но кто ты и откуда?",0,102,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Я <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> и итакийский царь.",0,103,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Сисифов сын, хитрец болтливый? Знаю…<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,104,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Он самый, да… Без дерзостей, старик!..",0,105,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Откуда ж ты в Сицилию забрался?",0,106,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Из Трои мы, от илионских мук…",0,107,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Иль не сумел сыскать пути в отчизну?",0,108,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Игрой ветров сюда я уловлен.",0,109,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Увы! Увы! Мы — тоже. Равный жребий…",0,110,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Так, значит, ты здесь тоже как в плену?",0,111,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Отбить хотел я у пиратов Вакха.",0,112,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Что за страна и кто же здесь живет?",0,113,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Нет выше гор в Сицилии, чем Этна.",0,114,0,0],["sd","(Показывает гору с ее утесами и далекой вершиной.)"],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","разглядывая местность"],["v","Но стены где ж и башни? Город где?",0,115,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Их нет, о гость! Утесы эти дики.",0,116,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Кому ж земля принадлежит? Зверям?",0,117,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","<span class=\"ch\" data-ch=\"kiklop\">Киклопы</span> здесь ютятся по пещерам.",0,118,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А правит кто? Цари иль сам народ?",0,119,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Они номады. Здесь никто не правит.",0,120,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Но сеют хлеб? Иль что ж они едят?",0,121,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Сыры, мясо и молоко — их пища.",0,122,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А сок лозы, отрадный Вакхов дар?",0,123,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Увы! Страна не знает ликований…",0,124,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","По крайней мере чтут они гостей?",0,125,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Да, мясо их они находят сочным…",0,126,0,0],["sd","Короткая пауза. Движение в толпе спутников <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Как? Убивают гостя и едят?",0,127,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Не уплывал еще никто от них покуда…",0,128,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А сам <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>, скажите, дома он?",0,129,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","С собаками гоняется за зверем.",0,130,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ты знаешь, что мы сделаем, Силен,",0,130,0,0],["v","Чтобы отсюда выбраться?",0,131,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Покуда",1,131,0,0],["v","Не знаю, но на все для вас готов.",0,132,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","показывая на пустые корзины"],["v","Продай нам хлеба, видишь — ни кусочка.",0,133,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Здесь мясо есть, а хлеба не найдешь.",0,134,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Что ж? Утолить и мясом можно голод…",0,135,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Найдется сыр, коровье молоко…",0,136,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Неси сюда… Посмотрим на припас…",0,137,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","А сколько ж нам ты золота отсыплешь?",0,138,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Не золота… а Вакхова питья.",0,139,0,0],["sd","(Приподнимая мех.)"],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","сладострастно"],["v","Отрадный звук… давно вина я не пил.",0,140,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","ослабляя ремень у мешка"],["v","Нам дал его сын бога, сам Марон.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,141,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","с улыбкой воспоминания"],["v","Я на руках носил его ребенком.",0,142,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Сказать ясней — он Вакхом и рожден.",0,143,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","будто не замечая мешка"],["v","А где ж вино, с тобою или в трюме?",0,144,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","приподнимая мех на руке"],["v","Вот этот мех наполнен им, старик.",0,145,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","с загоревшимися глазами"],["v","Разок глотнуть… Вина-то в этом мехе!",0,146,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","И столько же еще припасено.",0,147,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","О дивный ключ, ты радуешь нам сердце.",0,148,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","сотрясая вино"],["v","Не хочешь ли попробовать винца?",0,149,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","И следует… Какой же торг без пробы?",0,150,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","И чаша есть при мехе… В самый раз.",0,150,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","берет у него отвязанную чашу и подставляет под отверстие наклоненного <span class=\"ch\" data-ch=\"odissey\">Одиссеем</span> меха"],["v","Погромче лей… Чтоб помнилось, что пил…",0,151,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","наливает"],["v","Держи.",0,152,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","О, боги… Аромат какой!",0,153,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ты видишь аромат?",0,154,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Дыханьем слышу…",1,154,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Отведай-ка… так не словами только",0,155,0,0],["v","Оценишь ты вино мое.",0,155,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Плясать",1,155,0,0],["v","Нас приглашает Бромий… Го… го… го…",0,156,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А в горле-то бульбулькало приятно?",0,157,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Мне кажется, что до конца ногтей",0,158,0,0],["v","Проникли в нас живые токи Вакха.",0,159,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","И денег я тебе в придачу дам.",0,160,0,1],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","сладко дрожащим голосом"],["v","Ослабь завязки меха… Что нам деньги?",0,161,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А где ж сыры? Неси сперва ягнят.",0,162,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Все сделаю. И к черту всех хозяев!<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,163,0,0],["v","Душа горит, и за бокал вина",0,164,0,0],["v","Я отдал бы теперь стада киклопов",0,165,0,0],["v","Всех, сколько их ни есть. Стряхнуть тоску,",0,166,0,0],["v","А там… Хоть с этого утеса в море…",0,167,0,0],["v","Кто радостей не любит хмеля, тот —",0,168,0,0],["v","Безумец; сколько силы, сколько сладкой",0,169,0,0],["v","Возможности любить, какой игре",0,170,0,1],["v","Оно сулит свободу… а какие",0,170,0,0],["v","Для дерзких рук луга… И танцевать",0,171,0,0],["v","Зовет нас бог и отнимает память",0,172,0,0],["v","Прошедших зол… И побоюся я",0,173,0,0],["v","За сладкий дар так огорчить <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>,",0,174,0,0],["v","Чтоб плакал глаз единственный его?!",0,175,0,0],["sd","(Уходит в пещеру.)"],["scene","Явление четвертое","s5",2,5],["sd","Те же, без <span class=\"ch\" data-ch=\"silen\">Силена</span>."],["sp","Корифей"],["v","Позволишь, царь, поговорить с тобою?",0,175,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Друзьям я дам и дружеский ответ…",0,176,0,0],["sp","Корифей"],["v","Что, Трою взяв, вы взяли и Елену?",0,177,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Весь царский дом Приамов разорен.",0,178,0,0],["sp","Корифей"],["v","А молодой когда вы завладели",0,179,0,0],["v","Красавицей, я думаю, никто",0,180,0,1],["v","Не выпустил ее без поцелуя",0,180,0,0],["v","Из жарких рук?.. Мужья ж ей так милы…",0,181,0,0],["v","Изменщица… На пестрые штаны",0,182,0,0],["v","Польститься… Золотого ожерелья",0,183,0,0],["v","Не пропустить на белой шее и,",0,184,0,0],["v","Разнежившись, покинуть Менелая…",0,185,0,0],["v","А чем не человечек?.. Право, жен",0,186,0,0],["v","Хоть не было бы вовсе… Мне бы разве…",0,187,0,0],["scene","Явление пятое","s6",2,6],["sd","Те же и <span class=\"ch\" data-ch=\"silen\">Силен</span> из пещеры. За ними слуги несут ягнят-сосунков со связанными ногами и сыры в корзинах."],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Вот вам и стад богатство: это, царь,",0,188,0,0],["v","Ягнята на обед… А здесь сыров",0,189,0,0],["v","Обилие, из молока они",0,190,0,1],["v","Неснятого… Берите да подальше",0,190,0,0],["v","Бегите от пещеры… Только мне",0,191,0,0],["v","Не позабудьте дать взамен напиток",0,192,0,0],["v","Ликующего бога.",0,193,0,0],["sd","Слышен шум шагов и громкий голос, точно гул, со стороны дома."],["v","Ай… ай… ай…",1,193,0,0],["v","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> идет.",0,193,0,0],["sd","(Суетится и бросается во все стороны.)"],["v","Что делать нам? что делать?",0,194,4,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Погибли мы… Куда уйти, старик?",0,195,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Сюда, беги в пещеру, там и спрячься.",0,196,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Что говоришь? Да это ж западня!..",0,196,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","продолжая суетиться и без толку перекладывая с места на место ягнят, которых рабы побросали и которые пищат"],["v","Ничуть… ничуть… Есть уголки в пещере…",0,197,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Так нет же… Нет. Мне Трои не срамить",0,198,0,0],["v","От одного таясь, когда без счету",0,199,0,0],["v","Я за щитом выдерживал врагов",0,200,0,1],["v","Во Фригии. Пускай прилично мужу",0,200,0,0],["v","И воину погибнем, иль свою",0,201,0,0],["v","Мы унесем неповрежденной славу.",0,202,0,0],["scene","Явление шестое","s7",2,7],["sd","Те же и <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> со свитой, собаками; за ним тащат туши оленей, кабанов и диких коз. Он огромный, но с сравнительно маленькой головой и безобразным круглым и необыкновенно ярким глазом. Губы развороченные, красные и толстые. Несколько секунд напряженного молчания. Сатиры, мало обращая внимания на появление <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>, под шумок завели танцы, щелкают пальцами, играют на дудках и кружатся. <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> обращает внимание сначала только на них и не замечает точно застывшего <span class=\"ch\" data-ch=\"silen\">Силена</span>, который стоит весь красный и потный, рабов и молчаливого и мрачного <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>, который сидит, вытянувши ноги перед своей свитой."],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Смотрите-ка! Глядите-ка!.. Да что ж",0,203,0,0],["v","Тут деется?.. Тут оргия, бесчинство!",0,204,0,0],["v","Я вам не Вакх, и здесь не погремушки",0,205,0,0],["v","Из меди и не бубны вам…",0,206,0,0],["v","Ягнят",1,206,0,0],["v","Под маток положили ль вы по стойлам?",0,207,0,0],["v","Сосут-то хорошо ли? А удой",0,208,0,0],["v","В плетушках-то свернулся? Что ж? Услышу",0,209,0,0],["v","Ответ я ваш? Оглохли? Или ждете,",0,210,0,1],["v","Чтоб палка слезы вышибла?",0,210,0,0],["v","Сатиры стоят, потупившись в землю.",0,211,0,0],["sd","Не в землю, А на меня глядеть, вам говорят! (Топает ногой.)"],["sp","Корифей"],["dir","поднимая голову — другие ему усиленно подражают и задирают ее — тоном, где слышится и дерзость, и некоторая трусость, и ирония"],["v","Куда ж еще глядеть-то?.. Шеям больно,",0,212,0,0],["v","Так головы задрали… Вижу звезды",0,213,0,0],["v","И Ориона вижу в небесах.",0,213,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","немного успокоившись"],["v","А завтракать готово? Все в порядке?",0,214,0,0],["sp","Корифей"],["dir","развеселясь"],["v","Готово все… Лишь поспевай глотать…",0,215,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","И молока в ушаты надоили?",0,216,0,0],["sp","Корифей"],["v","О! Молока хоть бочку попроси…",0,216,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Коровьего, овечьего иль в смеси?",0,217,0,0],["sp","Корифей"],["v","Какого пожелаешь, только нас",0,218,0,0],["v","Ты с молоком не выпей ненароком.",0,219,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","с юмором висельника"],["v","Ну нет… Того гляди, что, в животе",0,220,0,1],["v","Распрыгавшись, вы нас бы уморили…",0,220,0,0],["sd","(Оборачивается и видит <span class=\"ch\" data-ch=\"odissey\">Одиссея</span> и спутников, потом ягнят, рабов и <span class=\"ch\" data-ch=\"silen\">Силена</span>.)"],["v","Ба… Это что ж? Перед моим двором",0,221,0,0],["v","Какой-то сброд… Разбойники иль воры",0,222,0,0],["v","Расположились? Обобрав загон,",0,223,0,0],["v","Ягнят моих они скрутили, прутья",0,224,0,0],["v","Из ивы им перетянули ноги.",0,225,0,0],["v","Ба… и сыры в тазах… А старику",0,225,0,0],["v","Наколотили лысину, должно быть.",0,226,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","притворяясь плачущим"],["v","Ой, лишенько, избит… и весь горю…",0,227,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","А кулаки-то чьи же погуляли?",0,228,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","указывая на греков"],["v","Вот этих, царь, воров, за то, что я",0,229,0,0],["v","Не позволял им грабить Полифема.",0,230,0,1],["sd","(Хнычет.)"],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Или они не знали, что я бог",0,230,0,0],["v","И от богов происхожу?",0,231,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Об этом",1,231,0,0],["v","Я говорил… А дерзкие добро",0,232,0,0],["v","Тем временем тянули… Ели сыр,",0,233,0,0],["v","Ягнят твоих хватали… Да грозились,",0,233,0,0],["v","Что самого тебя, мол, цепью свяжут",0,234,0,0],["v","Длиною в три локтя; еще кишки",0,235,0,0],["v","Тебе хотели выпустить… да спину",0,236,0,0],["v","В хоре легкий смешок.",0,236,0,0],["v","Бичами отработать, а потом,",0,237,0,0],["v","Сваливши в трюм, в оковах на продажу",0,238,0,0],["v","Его свезем в каменоломню, мол,",0,239,0,0],["v","Иль жернова на мельнице ворочать.",0,240,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","<span class=\"ch\" data-ch=\"silen\">Силену</span>"],["v","А ты не лжешь?",0,240,0,0],["sd","(Рабу.)"],["v","Поди-ка отточи",0,241,4,0],["v","Топор острей, да дров побольше вязку",0,242,0,0],["v","Сложи в костер. Подпалишь сушь, а мы",0,243,0,0],["v","Заколем их и скушаем. На углях",0,243,0,0],["v","Я подпеку одних, разняв сначала",0,244,0,0],["v","На свой манер, другие ж покипят",0,245,0,0],["v","В котле у нас, пока не разварятся…",0,246,0,0],["v","Дичь горная нам больше не вкусна, —",0,246,0,0],["v","Оленьего да львиного жаркого",0,247,0,0],["v","Мы досыта накушались — теперь",0,248,0,0],["v","И человек попался наконец-то.",0,249,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Новинка-то… куда же, господин,",0,250,0,1],["v","Приятнее — разнообразье в пище.",0,251,0,0],["v","А люди ведь у нас не всякий день.",0,252,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","вставая"],["v","Ты выслушай и нас теперь, Киклоп!",0,253,0,0],["v","Из корабля к твоей пещере мы",0,254,0,0],["v","Приблизились, чтобы купить припасов,",0,255,0,0],["v","И этот вор (указывая на <span class=\"ch\" data-ch=\"silen\">Силена</span>) нам за сосуд вина",0,256,0,0],["v","Твоих ягнят запродал и вручил,",0,257,0,0],["v","Бокал наш опорожнив; полюбовно",0,258,0,0],["v","Происходило дело, без насилья.",0,259,0,0],["v","Он пойман был с поличным, и теперь,",0,260,0,1],["v","Конечно, вылыгается старик.",0,260,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Ах, чтоб ты околел…",0,261,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Солгав, прибавишь.",1,261,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","поднимая руки"],["v","Отцом твоим клянусь, Киклоп, беру",0,262,0,0],["v","В свидетели Тритона, и Нерея,",0,263,0,0],["v","И дочерей его, и Калипсо,",0,264,0,0],["v","И чистою волной, и родом рыбьим…",0,265,0,0],["v","Уста я отмыкаю. О Киклоп,",0,265,0,0],["v","О миленький красавчик, Полифемчик,",0,266,0,0],["v","Не продавал, ей-богу ж… Пусть детей",0,267,0,0],["v","Лишусь, пускай с мученьем и без славы",0,268,0,0],["v","Они умрут — мне ль дети не милы?",0,269,0,0],["sp","Корифей"],["v","На голову твою слова те! Видел",0,270,0,1],["v","Своими я глазами, как гостям",0,270,0,0],["v","Ты продавал припасы. Если лгу…",0,271,0,0],["sd","Хор поднимает руки, и указательные пальцы обращаются на <span class=\"ch\" data-ch=\"silen\">Силена</span>; потом корифей торжественно:"],["v","Пускай отец помрет! (К <span class=\"ch\" data-ch=\"kiklop\">Киклопу</span>.) А ты гостей",0,272,0,0],["v","Не обижай!",0,273,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","останавливая знаком <span class=\"ch\" data-ch=\"silen\">Силена</span>, который хочет отвечать"],["v","Все враки. Я уверен,",1,273,0,0],["v","Как в Радаманте, в этом старике.<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,274,0,0],["v","Он, безусловно, прав…",0,275,0,0],["v","Ну порасспросим",1,275,0,0],["v","Теперь гостей. Откудова, дружки,",0,275,0,0],["v","Приплыли и какой вас вывел город?",0,276,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Рожденьем итакийцы, а плывем",0,277,0,0],["v","Из Трои; стены рушив ей, прибиты",0,278,0,0],["v","Дыханием морей к твоей земле.",0,279,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Так вы из тех, что в злобе за спартанку",0,280,0,1],["v","Негодную под самый Илион,",0,280,0,0],["v","На берега Скамандра, пробралися?..",0,281,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Да, мы из тех, и подвиг тяжек был.",0,282,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Стыдились бы, из-за одной жены,",0,282,0,0],["v","И шутка ли… Подняться на фригийцев…",0,283,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","То было дело бога, здесь людей",0,284,0,0],["v","Не обвиняй. Но, благородный отпрыск",0,285,0,0],["v","Царя пучин, тебя мы молим: в нас",0,285,0,0],["v","Почти свободных греков и к порогу",0,286,0,0],["v","Пришедших не с войною убивать",0,287,0,0],["v","Отдумай, царь; ты челюстям еды",0,287,0,0],["v","Не обещай, бессмертным ненавистной.",0,288,0,0],["v","Ведь нет угла в Элладе, где б отец",0,289,0,0],["v","Твой храма не имел теперь, а кто же",0,290,0,1],["v","Старался, как не мы, о том, Киклоп?",0,290,0,0],["v","Неколебим Тенара порт священный…",0,291,0,0],["v","Малейские скалистые ущелья<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,292,0,0],["v","Защищены, и Суний, что любим",0,292,0,0],["v","Палладою, и рудники его,",0,293,0,0],["v","И гавани Гереста. Нам ли было",0,294,0,0],["v","Терпеть, чтобы Элладу поносил",0,295,0,0],["v","Какой-нибудь фригиец? В славе доля",0,295,0,0],["v","Есть и твоя, <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>: ведь этот край,",0,296,0,0],["v","Подножие огнеточащей Этны, —",0,297,0,0],["v","Эллады угол также.",0,297,0,0],["v","Но к словам",1,297,0,0],["v","Моим склонись: для всех людей законом",0,298,0,0],["v","Является радушно принимать",0,299,0,0],["v","Крушенье потерпевших, им подарки",0,300,0,1],["v","Давать, их <em>одевать</em>… а не на вертел",0,300,0,0],["v","<em>Надев</em>, как мясо бычье, ими свой",0,301,0,0],["v","Желудок ублажать, Киклоп, да губы.",0,302,0,0],["v","Уж, кажется, достаточно земля",0,303,0,0],["v","Приамова Элладу разоряла<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,303,0,0],["v","И, досыта напившись крови, жен",0,304,0,0],["v","Оставила безмужними, губила",0,305,0,0],["v","Бездетных матерей, отцов седых…",0,306,0,0],["v","Коль ты еще для трапезы безбожной",0,306,0,0],["v","Оставшихся поджаривать начнешь,",0,307,0,0],["v","Куда ж идти тогда? О нет, моими",0,308,0,0],["v","Словами убедись и обуздай",0,309,0,0],["v","Ты ярость челюстей; хозяин будь",0,310,0,1],["v","Нам ласковый, а не палач. Губила",0,310,0,0],["v","Людей не раз бесчестная корысть.",0,311,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","А мой тебе совет: его до крошки",0,312,0,0],["v","Всего убрать, <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>. Один язык",0,313,0,0],["v","Перевари, и ты вития станешь.",0,314,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Для мудрого, мой мальчик, бог один —",0,315,0,0],["v","Богатство, да! А прочее — прикрасы",0,315,0,0],["v","Словесные, шумиха. Что отец",0,316,0,0],["v","Обстроился на мысах, где волна",0,317,0,0],["v","Кипит шумней, ну, это мы оставим…",0,318,0,0],["v","В толк не возьму, при чем тут мой отец.",0,319,0,0],["v","А что до молний Зевса, то покуда",0,320,0,1],["v","Я не считал, что Зевса мы слабей,",0,320,0,0],["v","Да и считать не буду. Объяснимся.",0,321,0,0],["v","Пока Кронид вам посылает дождь,",0,322,0,0],["v","Я здесь, в скале, под кровом и, теленка",0,323,0,0],["v","Поджаривши, а иногда и дичь,",0,324,0,0],["v","Съедаю за обедом, а потом",0,325,0,0],["v","Разляжешься, амфорой молока",0,325,0,0],["v","Себе желудок спрыснешь — и такой тут",0,326,0,0],["v","Поднимется, скажу тебе я, гром",0,327,0,0],["v","Под пеплосом, что впору бы и Зевсу.",0,328,0,0],["v","А если снег из Фракии нашлет",0,329,0,0],["v","С Бореем он, нам под звериной шкурой",0,330,0,1],["v","Да у огня — и холод нипочем.",0,330,0,0],["v","Ну а земля, хоти иль нет, а кормит",0,331,0,0],["v","Мои стада до тучности.",0,332,0,0],["v","Заметь,",1,332,0,0],["v","Что не богов я мясом угощаю,",0,333,0,0],["v","А сам себя. Утроба — вот наш бог,",0,334,0,0],["v","И главный бог при этом. Пища есть,",0,335,0,0],["v","И чем запить найдется на сегодня,",0,335,0,0],["v","Ничто не беспокоит — вот и Зевс",0,336,0,0],["v","Тебе, коль ты разумен. А людей,",0,337,0,0],["v","Которые изобрели закон,",0,338,0,0],["v","Чтоб нашу жизнь украсить, — к черту их!",0,339,0,0],["v","Себя твоим мясцом я побалую,",0,340,0,1],["v","Без этого нельзя, — а чтобы ты",0,340,0,0],["v","Не гневался, так вот тебе подарки:",0,341,0,0],["v","Огонь, вода — отцовский дар, — да этот",0,342,0,0],["v","Котел: при них разрезан на куски,",0,343,0,0],["v","Ты уместишься в нем, отлично, эллин,",0,343,0,0],["v","И сваришься.",0,344,0,0],["sd","(Обходит греков, так что они остаются между ним и входом в пещеру, и расставляет руки.)"],["v","А вы в пещеру, марш!..",0,345,4,0],["v","Поставлю вас у алтаря — для виду,",0,346,0,0],["v","Но угощусь зарезанными сам.",0,346,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","еще не входя в пещеру"],["v","Увы! Увы! Я избежал троянских",0,347,0,0],["v","Опасностей и моря… все затем,",0,348,0,0],["v","Чтобы безбожник дикий, как утес",0,349,0,0],["v","Без гавани, меня разбил. Паллада",0,350,0,1],["v","Владычица, о Зевса дочь, теперь",0,350,0,0],["v","Нас выручи! Приходится нам круче,",0,351,0,0],["v","Чем в Илионе было, и опасней.",0,352,0,0],["v","Ты, Зевс-гостеприимец, также, бог,",0,352,0,0],["v","Из своего надзвездного чертога,",0,353,0,0],["v","О, призри на несчастного, а если",0,354,0,0],["v","На это ты не смотришь или, бог,",0,354,0,0],["v","Ты этого не видишь, ты — не Зевс!",0,355,0,0],["v","Я более скажу, что ты — ничто!..",0,356,0,0],["sd","Уходит в пещеру вместе с <span class=\"ch\" data-ch=\"kiklop\">Киклопом</span>, Силеном, свитой и рабами, которые несут обратно ягнят. Суета, движение. Таскают дрова и воду."],["scene","Первый музыкальный антракт","s8",2,8],["sp","Хор"],["str","Строфа"],["v","Шире глотку готовь, Киклоп!",0,356,0,0],["v","Шире пасть разевай теперь…",0,357,0,0],["v","Гости сварены, сжарились,",0,358,0,0],["v","Под углями куски спеклись.",0,358,0,0],["v","Жуй, грызи, разрывай, Киклоп,",0,359,0,0],["v","На бараний пушистый ложися мех.",0,360,0,1],["str","Месод"],["v","Нас угощать не вздумай.",0,361,0,0],["v","Трюм одному себе",0,362,0,0],["v","Ты набивай, безбожник…",0,363,0,0],["v","Век бы тебя, пещера,",0,364,0,0],["v","Вас, нечестивца жертвы,",0,365,0,0],["v","Мясо людей не видеть, —",0,366,0,0],["v","Радость <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span> Этны.",0,367,0,0],["str","Антистрофа"],["v","Сердца, жалости нет в тебе,",0,368,0,0],["v","Гостя режешь молящего,",0,369,0,0],["v","Дом, очаг опозорены…",0,370,0,1],["v","Крошишь, рвешь, растираешь ты,",0,371,0,0],["v","Человечину в рот несешь",0,372,0,0],["v","Из кипящей воды, из-под угольев.",0,373,0,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s9",3,9],["v","Хор и <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> из пещеры.",0,374,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","О Зевс! О, что я видел там, в пещере,",0,375,0,0],["v","Не верится — то сказка, а не быль.",0,376,0,0],["sp","Корифей"],["v","В чем дело, Одиссей? Ужель безбожный",0,377,0,0],["v","Твоими сыт друзьями Полифем?",0,378,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Да, наглядевши пару и нащупав,",0,379,0,0],["v","Которые меж нами пожирней.",0,380,0,1],["sp","Корифей"],["v","Как это было, расскажи, несчастный…",0,380,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","В пещеру мы вступили, и огонь",0,381,0,0],["v","Разводит он сначала, на широкий",0,382,0,0],["v","Для этого очаг дубовых сучьев",0,383,0,0],["v","Телеги три сложивши… А потом",0,384,0,0],["v","Из зелени еловой ложе стелет",0,385,0,0],["v","Перед огнем себе и полный чан,",0,386,0,0],["v","Куда амфор войдет, пожалуй, с десять,",0,387,0,0],["v","Коровьим наполняет молоком",0,388,0,0],["v","Последнего удоя. Тут же рядом",0,389,0,0],["v","Плющом украшенный он ставит кубок",0,390,0,1],["v","Широкий, в три локтя, а глубиной",0,390,0,0],["v","В четыре целых мне казался он.",0,391,0,0],["v","Над очагом горящим он подвесил",0,391,0,0],["v","Котел для варки; после вертела",0,392,0,0],["v","Из дерева тернового, что были",0,392,0,0],["v","Закалены с конца в огне; готовит",0,393,0,0],["v","Еще <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> оструганные гладко",0,393,0,0],["v","Этнейские сосуды, топором",0,394,0,0],["v","Иссеченные также, чтобы кровью",0,395,0,0],["v","Наполнили их жертвы. А когда",0,395,0,0],["v","Для адской кухни все готово было,",0,396,0,0],["v","Из спутников выхватывает пару",0,396,0,0],["v","И убивает их; сперва один,",0,397,0,0],["v","Потом другой покончены без спеха,",0,397,0,0],["v","С известным ритмом даже. Первый был",0,398,0,0],["v","В котел опущен медный, а другого,",0,398,0,0],["v","За пятку ухватив, об острый выступ",0,399,0,0],["v","Безбожник головою ударяет,",0,400,0,1],["v","И, мозгу давши стечь, ножом с костей",0,401,0,0],["v","Наструганное мясо спек он, кости ж",0,402,0,0],["v","В котел вариться бросил. У меня",0,403,0,0],["v","В глазах стояли слезы, а пришлося",0,404,0,0],["v","Прислуживать <span class=\"ch\" data-ch=\"kiklop\">Киклопу</span>. Наши все,",0,405,0,0],["v","Как птицы, по углам прижались в страхе:",0,406,0,0],["v","Под кожей-то кровинки нет, поди…",0,407,0,0],["v","Но вот <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>, раздувшийся от мяса",0,408,0,0],["v","Товарищей, валится навзничь, дух",0,409,0,0],["v","Тяжелый из гортани испуская.",0,410,0,1],["v","Не божество ль тут озарило нас?",0,410,0,0],["v","Мароновым вином наполнив кубок,",0,411,0,0],["v","Я подношу ему и говорю:",0,412,0,0],["v","\"Царем морей рожденный, подивись,",0,413,0,0],["v","Какой у нас приносят лозы нектар, —",0,413,0,0],["v","То Вакха дар отрадный\". Через край",0,414,0,0],["v","Наполненный своей ужасной пищей,",0,415,0,0],["v","Он осушает кубок духом, руку",0,416,0,0],["v","Все выше поднимая, и затем",0,416,0,0],["v","В восторге восклицает: \"О, дражайший",0,417,0,0],["v","Из всех гостей, какой усладой ты",0,418,0,0],["v","Нам дал запить и кушанье какое\".",0,419,0,0],["v","Его увидя радость, я сейчас",0,420,0,1],["v","Другой бокал, но с твердою надеждой",0,420,0,0],["v","Что он, вином осиленный, моей",0,421,0,0],["v","Уж не минует мести. Доходило",0,422,0,0],["v","До песен дело даже, но, ему",0,422,0,0],["v","Возобновляя кубки, разжигал",0,423,0,0],["v","Утробу я усердно.",0,424,0,0],["sd","(Указывая на пещеру.)"],["v","Там, меж свиты,",0,424,4,0],["v","Что стонет по углам, <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> теперь",0,425,0,0],["v","Поет, положим, плохо, но пещера",0,426,0,0],["v","Кругом гудит. Я ж молча за порог.",0,426,0,0],["v","Себя и вас спасти хочу я, если",0,427,0,0],["v","Спасенья вы желаете. Но мне",0,428,0,0],["v","Должны сказать вы, точно ль вы хотите",0,428,0,0],["v","Покинуть дикаря и вновь обнять",0,429,0,0],["v","Своих наяд в чертоге Диониса?",0,430,0,1],["v","<span class=\"ch\" data-ch=\"silen\">Силен</span> душою с нами, но ослаб,",0,431,0,0],["v","От кубка не отстанет, точно птица",0,432,0,0],["v","Приклеился и только бьет крылом.",0,433,0,0],["v","Вы ж молоды, подумайте о Вакхе…",0,434,0,0],["v","Не чудищу чета ваш старый друг…",0,435,0,0],["sp","Корифей"],["v","О милый гость, дождемся ли мы дня,",0,436,0,0],["v","Чтобы в лицо безбожника не видеть?",0,437,0,0],["v","Поверишь ли, с которых пор вдовцы,",0,438,0,0],["v","А голод чем и утолить не знаем…",0,440,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Послушай-ка, как зверя мы казним",0,440,0,0],["v","Коварного, и ты получишь волю…",0,441,0,0],["sp","Корифей"],["v","О да, о да… Мне музыка кифар",0,442,0,0],["v","Лидийская не будет слаще вести,",0,443,0,0],["v","Что нет уже <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span> меж живых.",0,444,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Он, Вакховым питьем развеселен,",0,445,0,0],["v","Сбирается и братьев напоить.",0,446,0,0],["sp","Корифей"],["v","Ах, понял… Ты его в лесу зарежешь",0,447,0,0],["v","Наедине иль со скалы спихнешь…",0,448,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ну нет, мое желанье похитрее.",0,449,0,0],["sp","Корифей"],["v","А ну! Ведь ты прославленный хитрец.",0,450,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","В компанию его не отпущу я,",0,450,0,0],["v","Скажу ему, что этою усладой",0,451,0,0],["v","Не должен он делиться — пусть один",0,452,0,0],["v","Владеет ей. И пусть, осилен Вакхом,",0,453,0,0],["v","Он погрузится в сон, — наметил я",0,454,0,0],["v","Оливковую ветку и, кинжалом",0,455,0,0],["v","Позаострив да выстрогав ее,",0,456,0,0],["v","Спущу в огонь; когда же раскалится,",0,457,0,0],["v","Поднявши кол, <span class=\"ch\" data-ch=\"kiklop\">Киклопу</span> в глаз его",0,458,0,0],["v","Направлю, чтобы, выжженный, он вытек.",0,459,0,0],["v","Как мастер корабельный, свой бурав,",0,460,0,1],["v","Двойным ремнем кружа, вгоняет в доску,",0,460,0,0],["v","Так буду я вертеть в его глазу",0,461,0,0],["v","Горящий кол, пока зрачок не выжгу…",0,462,0,0],["sd","Корифей и хор"],["v","Ура!",0,463,0,0],["sp","Корифей"],["v","Какой восторг… Да тут с ума сойдешь.",0,464,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Затем тебя, товарищей и старца",0,465,0,0],["v","Спускаю в трюм ладьи своей, и нас",0,466,0,0],["v","От этих скал угонят пары весел.",0,467,0,0],["sp","Корифей"],["v","А я, скажи, я в этом торжестве,",0,468,0,0],["v","В буравленье <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span> головешкой,",0,469,0,0],["v","Участвовать могу? С тобой его",0,470,0,1],["v","Казнить?",0,470,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ну да! Необходимо даже",1,470,0,0],["v","Участие твое. Ведь кол велик.",0,471,0,0],["sp","Корифей"],["v","О, право б, я за груз со ста телег",0,472,0,0],["v","Теперь взялся. Зверюгу мы погубим,",0,473,0,0],["v","И глаз ему с тобой разворошим",0,474,0,0],["v","Мы, как гнездо осиное.",0,475,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","останавливая жестом излишние восторги сатиров"],["v","Довольно.",1,475,0,0],["v","Ты план мой рассмотрел уж. А когда",0,475,0,0],["v","Приспеет срок, услышишь приказанья",0,476,0,0],["v","Строителя, — я спутников моих",0,477,0,0],["v","Не для того ж покинул там, конечно,",0,478,0,0],["v","Чтоб одному спастись. И случай есть",0,479,0,0],["v","Уйти теперь подальше от <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>,",0,480,0,1],["v","Но оставлять товарищей, сюда",0,481,0,0],["v","За мною же пришедших, не годится.",0,482,0,0],["sd","(Уходит в пещеру.)"],["scene","Второй музыкальный антракт","s10",3,10],["sd","Первое полухорие"],["v","Кто первый и кто возьмется второй",0,483,0,0],["v","За кол с раскаленным концом,",0,484,0,0],["v","Чтоб око <span class=\"ch\" data-ch=\"kiklop\">Киклопу</span> буравить",0,485,0,0],["v","И свет погасить там навеки?",0,486,0,0],["v","Из пещеры громкое пение.<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,487,0,0],["sd","Второе полухорие"],["v","Потише… Потише! Идет…",0,488,0,0],["v","Как пьян он… О, дикая песня!",0,489,0,0],["v","Чертог свой покинул скалистый…",0,490,0,1],["v","Невежа…",0,491,0,0],["sd","Полифем в загороде."],["v","Заплачет он скоро!",1,491,0,0],["v","Покажем, друзья, дикарю,",0,492,0,0],["v","Как, Бромия славя, ликуют,",0,493,0,0],["v","Пока еще солнце он видит…",0,494,0,0],["sd","За загородой показывается <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>, красный, он шатается. За ним — Силен, совсем багровый, и свита. Рабы с чаном и <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> в венке, который постоянно сваливается. Вся борода у него в пене и одежда в большом беспорядке; он размахивает руками. Сзади всех <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>, у него в руке щит."],["sd","Полный хор (быстро, в сопровождении хороводной пляски — сикинниды)"],["str","Строфа I"],["v","Счастье жизни — пир веселый,",0,495,0,0],["v","Чтоб вино ключом бежало,",0,496,0,0],["v","А рука на мягком ложе",0,497,0,0],["v","Друга к сердцу прижимала.",0,498,0,0],["v","Иль златистый, умащенный",0,499,0,0],["v","Разметать по ложу локон",0,500,0,1],["v","И молить, изнемогая:",0,501,0,0],["v","«Отвори мне, дорогая».",0,502,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","подплясывая и стараясь подражать напеву сатиров"],["str","Строфа II"],["v","Тр<em>а</em>-л<em>а</em>-л<em>а</em> да т<em>а</em>рам-б<em>а</em>рам,",0,503,0,0],["v","Что за пиво, что за варка…",0,504,0,0],["sd","(Икает.)"],["v","Мой живот, ей-ей, товаром…",0,505,0,0],["v","Полон доверху, как барка.",0,506,0,0],["sd","(Спотыкается, его поддерживают <span class=\"ch\" data-ch=\"silen\">Силен</span> и рабы.)"],["v","Эх ты, травка моя, травка,",0,507,0,0],["v","Хорошо на травке спится,",0,508,0,0],["v","Я ж кутить иду к киклопам…",0,509,0,0],["v","Эй, почтенный… дай напиться…",0,510,0,1],["sp","Хор"],["str","Строфа III"],["v","Ослепляя нас красою,",0,511,0,0],["v","И влюбленный и любимый,",0,512,0,0],["v","Вот чертог он покидает.",0,513,0,0],["v","Сень, кропимая росою,",0,514,0,0],["v","Факел, пламенем палимый,",0,515,0,0],["v","И невеста ожидает",0,516,0,0],["v","Там тебя — и розы кущей",0,517,0,0],["v","Оттенят там лик цветущий…",0,518,0,0],["act","Действие третье","a4","III"],["scene","Явление восьмое","s11",4,11],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Послушай нас, Киклоп, ведь этот Вакх,",0,519,0,0],["v","Которым я поил тебя, нам близок.",0,520,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Постой… А Вакх какой же будет бог?",0,521,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Сильнее нет для наших наслаждений.",0,522,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","икая"],["v","Да, отрыгнуть его… и то добро.",0,523,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Такой уж бог, что никому не вреден.",0,524,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Забавно: бог, а сам живет в мешке!",0,525,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Куда ни сунь его, на все согласен.",0,526,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","внезапно рассердившись и топая ногой"],["v","А все ж богам не место в кожах жить!",0,527,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Вот как… А сам? Тебе неловко в коже?..",0,528,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Черт с ним, с мешком… Нам было бы винцо!",0,529,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Так в чем же суть? Тяни да развлекайся.",0,530,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","А братьям и попробовать не дать?",0,531,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Как пьешь один, так будто ты важнее.",0,532,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","А поделись — так ты друзьям милей.",0,533,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ведь что ни пир — то кулаки да ссоры.",0,534,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Ну нет, меня и пьяного не тронь.",0,535,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Ох, подкутил, так оставайся дома.",0,536,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Кто, захмелев, уходит с пира — глуп!",0,537,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А кто и пьян и дома — тот философ.",0,538,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Так как же, брат <span class=\"ch\" data-ch=\"silen\">Силен</span>, остаться, что ль?",0,539,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Конечно же. Зачем винцом делиться?",0,540,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","разваливаясь на траве"],["v","Да, в сущности… Не дурно ведь и тут:",0,540,0,0],["v","Трава такая мягкая, цветочки…",0,541,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","стараясь положить его спиной к вину, которое рабы в кратере поставили на землю"],["v","На солнышке-то славно попивать.",0,542,0,0],["sd","(Припал к чашке.)"],["v","Вот вытянься получше… Боком… боком…",0,543,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Эге… А чан-то будет за спиной?..",0,544,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","подмигивая <span class=\"ch\" data-ch=\"odissey\">Одиссею</span> и прихлебывая"],["v","Чтоб кто не опрокинул.",0,545,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","не ворочаясь"],["v","Потихоньку",1,545,0,0],["v","Ты, кажется, там тянешь, брат. Поставь-ка",0,545,0,0],["v","Кратер-то посередке.",0,546,0,0],["sd","Вино переставляют перед <span class=\"ch\" data-ch=\"kiklop\">Киклопом</span>, но на некотором от него расстоянии."],["sd","(К <span class=\"ch\" data-ch=\"odissey\">Одиссею</span>.)"],["v","Ты же, гость,",0,547,4,0],["v","Как звать тебя по имени, скажи нам.",0,548,0,0],["sd","Подманивает его пальцами. <span class=\"ch\" data-ch=\"odissey\">Одиссей</span> подходит и, пока он находится между кратером и <span class=\"ch\" data-ch=\"kiklop\">Киклопом</span>, <span class=\"ch\" data-ch=\"silen\">Силен</span> пьет прямо из чана."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Никто. Тебя ж за что благодарить?",0,549,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","хохочет"],["v","Товарищей… я закушу тобою.",0,550,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","загадочно"],["v","А что же? Твой подарок не дурен…",0,550,0,0],["sd","(Отходит.)"],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","замечая <span class=\"ch\" data-ch=\"silen\">Силена</span>, который между тем отскочил от чана"],["v","Эй ты… Опять лизнул-таки винишка…",0,551,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","вытирая губы"],["v","Не я его, оно меня, <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>.",0,552,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Вино тебя не любит… Ты — любитель",0,553,0,0],["v","Его, но… неудачный…",0,554,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","хлопая еще бокал"],["v","Вот… вот… вот…",1,554,0,0],["v","Я ль не красив, а, говоришь, не любит.",0,555,0,0],["sd","(Медленно наливает в чашу, но никак не нальет до края, потому что постоянно отхлебывает.)"],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","следя за его движениями посоловелым глазом"],["sd","Ну, наливай полнее… (Кричит.) Только лей!"],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","с серьезным видом поднимая чашу и отворачиваясь от <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>"],["v","Смешалось ли как следует, посмотрим.<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,556,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Ох, смерть моя, давай!",0,557,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Постой, сперва",1,557,0,0],["v","Венок надень.",0,558,0,0],["sd","(Поправляет ему венок.)"],["v","А я слегка пригублю.",0,559,4,0],["sd","(Отпивает половину.)"],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Проклятый виночерпий!",0,560,0,1],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Просто чудо",1,560,0,0],["v","Что за винцо! А ты сперва утрись!",0,560,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","вытираясь"],["v","Все вытерто, и борода и губы.",0,561,0,0],["sd","(Протягивает руку.)"],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Ну-с… Локоть закругли теперь, как я,",0,562,0,0],["v","И пей…",0,563,0,0],["sd","(Через чашу.)"],["v","Как я тяну…",0,564,3,0],["sd","(Не отрываясь.)"],["v","Вернее, выпил.",0,565,4,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","приподнимаясь"],["v","Не смей… Не смей.",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","опрокидывая чашу"],["v","Хоть залпом, а добро…",1,565,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Ты становися, гость, и угощай нас.",0,566,0,0],["sd","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span> отталкивает <span class=\"ch\" data-ch=\"silen\">Силена</span> от чана и становится возле него, отняв у старика чашу."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","А что ж, рукам не привыкать к лозе…",0,567,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Ну, наливай…",0,568,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","быстро наливая в чашу чистого вина из меха"],["v","Помалкивай — получишь…",1,568,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Легко сказать: молчи — а если пьян?",0,569,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","бережно поднося полную темную чашу, внушительным тоном"],["v","Бери и пей, но пей не отрываясь,",0,570,0,1],["v","Чтоб не осталось капли и на дне.",0,571,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","проникаясь его настроением, облизнул губы и принимает чашу"],["sd","Да здравствует лоза и с виноградом! (Начинает медленно пить и пьет довольно долго. Тем временем — )"],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Коль трапезу обильную запьешь",0,572,0,0],["v","Как следует и оросишь желудок,",0,573,0,0],["v","Хотя бы он не жаждал, — сладок сон,",0,574,0,0],["v","А не допьешь… так горло пересохнет.",0,575,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","допив, отдает чашу. Глаз замаслился, загорелся. Приходит в чадный восторг"],["v","Фу… фу… Совсем тонул. Насилу выплыл!",0,576,0,0],["v","Чудесно как! И небо и земля",0,577,0,0],["v","Смешалися и кружатся… Глядите:",0,578,0,0],["v","Вот Зевсов трон и весь священный род",0,580,0,1],["v","Богов…",0,580,0,0],["v","Но только вы, Хариты, даром",1,580,0,0],["v","Чаруете <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>. Целовать",0,581,0,0],["v","Я вас не собираюсь…",0,582,0,0],["sd","(Обнимает <span class=\"ch\" data-ch=\"silen\">Силена</span>, который слабо отбивается.)"],["v","Ганимеда",0,582,4,0],["v","Довольно с нас и этого, чтоб ночь",0,583,0,0],["v","Нам усладить. Вообще предпочитаю",0,584,0,0],["v","Я мальчиков другому полу…",0,585,0,0],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","в ужасе"],["v","Как?",1,585,0,0],["v","Я — Ганимед Кронида? Что ты? Что ты?",0,585,0,0],["sd","(Хочет вырваться, но <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> поднимает его и держит на руках, старик только бессильно барахтается.)"],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Сын Дардана… И им я завладел.",0,586,0,0],["sd","(Показывая старика зрителям.)"],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["v","Ой, смерть моя… Как вынесу я это?",0,587,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","мурлыча среди поцелуев, от которых <span class=\"ch\" data-ch=\"silen\">Силен</span> отбивается"],["v","Отталкивать любовника за то,",0,587,0,0],["v","Что выпил он… Капризничать… Ну нет.",0,588,0,0],["sd","(Бежит с своей ношей в пещеру.)"],["sp","<span class=\"ch\" data-ch=\"silen\">Силен</span>"],["dir","со стоном"],["v","Увы! Сейчас вина познаю горечь.",0,589,0,0],["scene","Явление девятое","s12",4,12],["sd","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span> и хор."],["sd","⟨<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>⟩"],["v","Смелей теперь, о Вакха сыновья",0,590,0,1],["v","И дети благородные! Ушел он",0,590,0,0],["v","И скоро, сном размаян, изрыгнет",0,591,0,0],["v","Бессовестный обед свой. Головешка",0,592,0,0],["v","В пещере уж курится, и осталось",0,593,0,0],["v","<span class=\"ch\" data-ch=\"kiklop\">Киклопу</span> глаз спалить…",0,593,0,0],["v","Знаки волнения в хоре.",0,594,0,0],["v","Но мужем будь.",1,594,0,0],["sp","Корифей"],["dir","ударяя себя в грудь"],["v","Из камня и железа будет сердце…",0,595,0,0],["v","Но в дом войди, покуда над отцом",0,596,0,0],["v","Чего-нибудь ужасного не сделал",0,596,0,0],["v","Киклоп, а мы готовы, <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>.",0,597,0,0],["sd","(Ободряя товарищей, которые все больше волнуются.)"],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","к вершине Этны"],["v","Гефест, о царь Этнейский, — глаз соседу",0,598,0,0],["v","Испепелив блестящий, разом, бог,",0,599,0,0],["v","Освободись от Полифема!..",0,600,0,1],["v","Ты же,",1,600,0,0],["v","Питомец Ночи, Сон, всей силой, Сон,",0,600,0,0],["v","На зверя напади, что ненавистен",0,601,0,0],["v","Бессмертным.",0,602,0,0],["v","Нас же, боги, — <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>",1,602,0,0],["v","И моряков, украшенных венцом",0,603,0,0],["v","Троянских дел, — не отдавайте в руки",0,604,0,0],["v","Чудовищу, которое не чтит",0,605,0,0],["v","Ни вас, ни нас… Иначе Случай станет",0,605,0,0],["v","Не только божеством, — сильней богов…",0,606,0,0],["sd","(Уходит в пещеру.)"],["scene","Третий музыкальный антракт","s13",4,13],["sp","Хор"],["v","Скоро кольцо ему шею",0,607,0,0],["v","Тесно, ужом обхватит —",0,608,0,0],["v","Этому варвару, зверю,",0,609,0,0],["v","Что не щадит гостей…",0,610,0,1],["v","Скоро… скоро спалит огонь",0,610,0,0],["v","Светлый зрачок ему:",0,611,0,0],["v","Уж под золой сокрыт",0,612,0,0],["v","Кол раскаленный. Ах,",0,613,0,0],["v","Пусть же Марон",0,614,0,0],["v","Дело вершит теперь!",0,615,0,0],["v","Зверь уж безумствует,",0,615,0,0],["v","Пусть и погибнет зверь.",0,616,0,0],["sd","(Все громче и громче.)"],["v","Этот постылый дом",0,617,0,0],["v","Кинуть давно пора,",0,618,0,0],["v","Кинуть для милого,",0,619,0,0],["sd","Пляска."],["v","Плющом венчанного…<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,620,0,1],["v","Господи, Господи,",0,621,0,0],["v","Час тот настанет ли?..",0,622,0,0],["act","Действие четвертое","a5","IV"],["scene","Явление десятое","s14",5,14],["v","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span> из пещеры тянет огромный кол.",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Да тише ж вы, козлята! Ради бога,<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,624,0,0],["v","Сожмите губы крепче…",0,625,0,0],["sd","Пляска прекращается."],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","грозя пальцем"],["v","Не дохни…",1,625,0,0],["v","Моргнуть не смей, чихнуть не смей! <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>",0,626,0,0],["v","Не разбуди ты как-нибудь, пока",0,627,0,0],["v","Мы не спалим сверкающего глаза.",0,628,0,0],["sp","Корифей"],["v","Меж челюстей и то зажали дух.",0,629,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Так марш за мной! Берись за головешку!",0,630,0,1],["v","Она уж накалилась хорошо.",0,631,0,0],["sd","Мимическая сцена. Сатиры прячутся друг за друга. Некоторые из-за товарищей стараются разглядеть раскаленный конец кола и внутренность пещеры, из которой несется храп."],["sp","Корифей"],["dir","робко выступая вперед, дрожащим голосом"],["v","Не выберешь ли сам, кому сначала",0,632,0,0],["v","<span class=\"ch\" data-ch=\"kiklop\">Киклопу</span> глаз буравить, чтобы мы",0,633,0,0],["sd","Его дергают сзади."],["v","Участвовать могли в подобном счастье.",0,634,0,0],["sd","Голоса из хора"],["v","Нам несколько далеко… Не достать",0,635,0,0],["v","Из-за дверей колом до глаза будет.",0,636,0,0],["sd","Голос из хора"],["v","А я так охромел… И отчего бы?",0,637,0,0],["sd","Другой голос"],["v","Вот так же, как и я. И сам не знаю,",0,638,0,0],["v","Как вывихнул я ногу… А болит.",0,639,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Какой же вывих стоя?",0,640,0,1],["v","Один",1,640,0,0],["v","Мне золою",1,640,0,0],["v","Запорошило глаз… Не вижу вот.",0,640,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","сдержанным шепотом"],["v","Негодные союзники… Трусишки.",0,641,0,0],["sp","Корифей"],["v","Коли спины или хребта мне жаль",0,642,0,0],["v","И если не хочу я, чтоб ударом",0,643,0,0],["v","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span> мне зубы вышиб, так ужель",0,643,0,0],["v","Поэтому я трус?",0,644,0,0],["sd","(Мягко.)"],["v","Мы знаем песню",0,645,4,0],["v","Волшебную Орфея: под нее",0,646,0,0],["v","Сама собой вонзится головешка",0,646,0,0],["v","Рожденью одноглазому земли,",0,647,0,0],["v","Через зрачок, воспламеняя череп…",0,648,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Я знал давно, что сердцем ты таков,",0,649,0,0],["v","А с этих пор запомню тверже.",0,650,0,1],["v","Видно,",1,650,0,0],["v","Приходится нам взяться за своих.",0,650,0,0],["v","А ты, коль силой слаб, по крайней мере",0,651,0,0],["v","Хоть подгоняй товарищей, словами",0,652,0,0],["v","Им бодрости прибавь…",0,652,0,0],["sd","(Уходит в пещеру.)"],["sp","Корифей"],["v","Вот это так.",1,652,0,0],["v","Мы смелы, как карийцы,<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,653,0,0],["v","И если лишь за поощреньем дело,",0,654,0,0],["v","Тогда <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>, тебе несдобровать.",0,655,0,0],["scene","Явление одиннадцатое","s15",5,15],["sd","На сцене никого. В пещере сдержанные голоса и храп, который прерывается воем, сначала слабым, потом сильнее."],["sp","Хор"],["v","Смелей, итакийцы,",0,655,0,0],["v","Спешите, толкайте,",0,656,0,0],["v","И бровь гостееду",0,657,0,0],["v","Вы в уголь, и веки",0,657,0,0],["v","Вы пастыря Этны",0,658,0,0],["v","Палите, сжигайте!",0,659,0,0],["v","Сверло-то запустишь,",0,660,0,1],["v","Да тотчас из глаза,",0,660,0,0],["v","То как бы от боли",0,661,0,0],["v","Он бед не наделал.",0,662,0,0],["scene","Явление двенадцатое","s16",5,16],["sd","Из пещеры в ужасном виде показывается <span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>. За ним <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>, свита и <span class=\"ch\" data-ch=\"silen\">Силен</span>, которые осторожно его обходят и сходят в орхестру к хору. <span class=\"ch\" data-ch=\"silen\">Силен</span> прижимает к груди, как ребенка, мех."],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","О, горе! Глаз спалили… углем глаз.",0,662,0,0],["sd","(Стонет.)"],["sp","Корифей"],["v","Какой пеан чудесный! Еще разик…<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,663,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Ой лихо мне… Унижен и погиб.",0,664,0,0],["sd","(Становясь в воротах и расставляя руки и ноги.)"],["v","А все-таки отсюда не уйдете,",0,665,0,0],["v","Ничтожные людишки, ликовать",0,665,0,0],["v","Покуда погодите. Я в воротах",0,666,0,0],["v","Подстерегу вас, от меня теперь",0,667,0,0],["v","Не вырвешься!",0,667,0,0],["sd","(Шарит.)"],["v","⟨Всех приберу к рукам⟩",0,668,4,0],["sp","Корифей"],["v","Чего кричишь, Киклоп?",0,669,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Погиб я, умер.",1,669,0,0],["sp","Корифей"],["v","Да, скверный вид.",0,670,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Несчастнейший, прибавь.",1,670,0,0],["sp","Корифей"],["v","Ты на костер свалился в пьяном виде?",0,670,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","сквозь слезы"],["v","Никто… Никто…",0,671,0,0],["sp","Корифей"],["v","Никто не виноват?",1,671,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","И веки выжег он же…",0,672,0,0],["sp","Корифей"],["v","Видишь, значит?",1,672,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Тебе бы так, мальчишка!",0,673,0,0],["sp","Корифей"],["v","Сам же ты",1,673,0,0],["v","Нам говорил: никто…",0,674,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Все шутки! Где",1,674,0,0],["v","Никто, скажи мне лучше…",0,675,0,0],["sp","Корифей"],["v","Где? Нигде.",1,675,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Пойми ж: меня ахеец изувечил,",0,676,0,0],["v","Тот самый, что в напитке утопил.",0,677,0,0],["sp","Корифей"],["v","И враг да и атлет — вино — не слабый.<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,678,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Ради богов… Ушли они иль тут?",0,679,0,0],["sp","Корифей"],["v","Они таятся молча под навесом.",0,680,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Откуда же?",0,681,0,0],["sp","Корифей"],["sd","Направо от тебя."],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","нетерпеливо шаря"],["v","Да где… где?..",0,682,0,0],["sp","Корифей"],["v","К скале они прижались…",1,682,0,0],["v","Поймал?",0,683,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","с разбега наскочив на выступ скалы"],["v","Какое!.. Новая беда.",1,683,0,0],["v","Хватился головой об камень.",0,684,0,0],["sp","Корифей"],["v","Так удрали?",1,684,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Не ты же ль говорил?",0,685,0,0],["sp","Корифей"],["v","Не там ловил…",1,685,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Да где ж ловить?",0,686,0,0],["sp","Корифей"],["v","Ты забирай налево.",1,686,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Смеетесь вы… Глумитесь над бедой.",0,687,0,0],["sp","Корифей"],["v","Теперь уж нет… Перед тобой… Никто…",0,688,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","кричит"],["v","Проклятый грек… Да где ж ты?",0,689,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Далеко…",1,689,0,0],["v","И сторожу особу <span class=\"ch\" data-ch=\"odissey\">Одиссея</span>…",0,690,0,1],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Как ты сказал? Ты имя изменил.",0,690,0,0],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["v","Нет, так отец нас назвал, <span class=\"ch\" data-ch=\"odissey\">Одиссеем</span>.",0,691,0,0],["v","А за обед, Киклоп, ты заплатил;",0,692,0,0],["v","Троянский я стыдом покрыл бы пепел,",0,693,0,0],["v","Не отомстив за съеденных друзей.",0,694,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["v","Увы!",0,695,0,0],["v","Сбывается пророчество. Давно уж",0,695,0,0],["v","Мне сказано, что именно тобой",0,696,0,0],["v","И на пути из Трои буду глаза",0,697,0,0],["v","Лишен… Но и тебе пророк тогда",0,698,0,0],["v","Судил носиться долго по пучинам<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,699,0,0],["v","За это преступленье, <span class=\"ch\" data-ch=\"odissey\">Одиссей</span>.",0,700,0,1],["sp","<span class=\"ch\" data-ch=\"odissey\">Одиссей</span>"],["dir","со злобой"],["v","Сиди да плачь… Я что сказал, то сделал.",0,701,0,0],["v","На мыс теперь… Да, отвязав ладью,",0,702,0,0],["v","По волнам сицилийским — и в отчизну.",0,703,0,0],["sp","<span class=\"ch\" data-ch=\"kiklop\">Киклоп</span>"],["dir","отломив огромный камень и размахивая им"],["v","Стоп… Я отбил кусок скалы, и вас",0,704,0,0],["v","Он в порошок сотрет и с вашей лодкой…",0,705,0,0],["sd","Все уходят, кроме <span class=\"ch\" data-ch=\"kiklop\">Киклопа</span>, который подвигается около скалы, ощупывая путь одной рукой и придерживая ушибленную голову другой."],["v","Хоть я и слеп… Но есть в скале проход,",0,706,0,0],["v","И я, на мыс взобравшись, вас заспею…",0,707,0,0],["sp","Корифей"],["dir","кричит издали"],["v","Мы с <span class=\"ch\" data-ch=\"odissey\">Одиссеем</span> также… А потом",0,708,0,0],["v","Туда, к себе, в вакхическую свиту.",0,709,0,0],["v","Сцена и орхестра пустеют.",0,710,0,0],["h1","Комментарий","comm"],["p","В датировке этого произведения Еврипида исследователи расходятся, относя его то к концу 40-х годов V в., то к последнему периоду жизни поэта. Наблюдения над языком и метрикой, свободное употребление трех актеров, а также возможные намеки на события, связанные с Сицилийской экспедицией, делают, по-видимому, наиболее правдоподобной постановку «Киклопа» около 414 г."],["p","Сюжет драмы восходит непосредственно к рассказу из IX книги гомеровской «Одиссеи», — разумеется, с теми отклонениями, которые диктовались условиями сцены. Прежде всего, поскольку действие происходит не внутри пещеры, а перед ней, ослепление Полифема продиктовано не столько стремлением Одиссея спастись от страшного людоеда (ср. ст. 480), сколько местью за растерзанных им товарищей (ст. 694). Столь же естественно для древнегреческой драмы, что ее действие происходит в течение одного дня, в то время как в эпосе оно начинается вечером первого дня, захватывает следующие за ним две ночи и заканчивается на третий день. Наконец, самый жанр драмы сатиров требовал непременного участия этих озорных и трусливых спутников Диониса, которых Еврипид ввел при помощи распространенного в древнегреческой драме приема: их хозяин Дионис был похищен пиратами, сатиры отправились на его поиски и в результате кораблекрушения оказались в Сицилии, где они и попали в руки Полифема (см. ст. 11 — 35). Что касается Сицилии как места действия «Киклопа», то и здесь Еврипид избирает не гомеровскую версию (в «Одиссее» киклопы обитают на неизвестном полусказочном острове), а более позднюю, ассоциировавшую деятельность киклопов как подручных бога-кузнеца Гефеста с огнедышащей горой Этной на Сицилии (см. ст. 599 сл.). Возможно, что в драматическую поэзию этот вариант мифа ввел впервые сицилийский комедиограф Эпихарм (первая половина V в.), написавший комедию «Киклоп»; одноименную сатировскую драму поставил также афинский драматург Аристий (середина V в.). От обоих произведений ничего не сохранилось, и можно только констатировать, что в обработке этого гомеровского повествования для сцены Еврипид имел предшественников."],["p","Хотя «Киклоп» является до сих пор единственным целиком сохранившимся образцом драмы сатиров, опубликованные в 1911 г. довольно крупные папирусные отрывки сатировской драмы Софокла «Следопыты», а в 1930 — 1940-х годах — фрагменты двух произведений того же жанра Эсхила, позволяют составить теперь более отчетливое представление как о специфике жанра в целом, так и об ее отражении в творчестве Еврипида. По сообщению Аристотеля («Поэтика», гл. 4), именно из сатировской драмы, возникшей в рамках земледельческого культа бога Диониса, выросла древнегреческая трагедия, очень скоро освободившаяся от первоначальной шутливости, свойственной представлению с участием сатиров. Однако происхождение трагедии из культа Диониса не было забыто: на Великие Дионисии, ежегодно справлявшиеся в честь бога, каждый из соревнующихся драматургов был обязан поставить, кроме трех трагедий, заключительную драму сатиров. Если трагедии были связаны единством сюжета, то и сатировская драма разрабатывала какой-нибудь побочный эпизод из того же круга сказаний (так было обычно у Эсхила); в других случаях содержание сатировской драмы могло заимствоваться из любого мифа, дававшего возможность для несколько юмористической обработки. Ее героями наряду с обязательным хором сатиров во главе с добродушным пьяницей — «папашей» Силеном часто являлись известные хитрецы, вроде Одиссея или Сисифа, или богатыри, заброшенные судьбой в далекие страны, где им приходилось вступать в борьбу с каким-нибудь чудовищем, в плену у которого находятся сатиры. Серьезная нравственная проблематика, представлявшая отличительную особенность трагедий, была противопоказана сатировской драме; назначение ее состояло не в последнюю очередь в том, чтобы из мира трагических конфликтов и потрясений вернуть зрителя в атмосферу веселого весеннего празднества Диониса."],["p","«Киклоп» Еврипида по своему сюжету и расстановке действующих лиц (чудовищный людоед Полифем и хитрец Одиссей; храбрые на словах, но трусливые в опасности сатиры) целиком находятся в русле основных закономерностей жанра. Однако рассуждения Полифема о «праве сильного», отражающие распространенные в Афинах в конце V в. взгляды «младших софистов», и его дискуссия с Одиссеем об отношении к Троянской войне вносят в сатировскую драму серьезные тона, отчасти лишающие ее необходимой легкости и непринужденности. Эти обязательные качества драмы сатиров, по-видимому, вообще мало привлекали к себе интерес Еврипида: за свою долгую творческую жизнь он написал не более семи-восьми произведений этого жанра, предпочитая, вероятно, ставить в качестве четвертой части тетралогии трагедию с благополучным концом, типа «Алькесты»."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"]],"n":{"k1":["Ст. 3 — 4. …безумьем Геры охваченный…","Согласно мифологической традиции, ревнивая Гера поразила Диониса безумием, когда он был уже юношей; Еврипид же изображает здесь дело таким образом, что гнев Геры обрушился на Диониса еще в раннем детстве. Такой вариант мифа объясняется, вероятно, тем, что одной из сценических функций «папаши» Силена была роль няньки при маленьком Дионисе. Таким он был изображен, например, в недошедшей сатировской драме Софокла «Дионис-младенец». Ореады — горные нимфы."],"k2":["Ст. 5 — 9. …сраженье с рожденными Землею.","Если участие Диониса в битве богов с гигантами («рожденными Землею») не противоречит мифологической традиции, то «подвиг» Силена — пустое бахвальство: Энкелад был сражен Афиной."],"k3":["Ст. 18. Малея","мыс на крайней юго-восточной оконечности Пелопоннеса."],"k4":["Ст. 21. …Царя морского дети…","Согласно «Одиссее», только Полифем был сыном Посейдона."],"k5":["Ст. 39. Алфея","жена калидонского царя Энея, родившая от союза с Дионисом Деяниру, будущую жену Геракла."],"k6":["Ст. 104. Сисифов сын.","Существовала версия мифа, что Антиклея, мать Одиссея, еще до своего замужества сошлась с Сисифом, от которого и родила Одиссея; таким образом, хитрец сын получал достойного его хитреца отца."],"k7":["Ст. 141. Марон.","В «Одиссее» (IX, 197 — 211) так зовут жреца Аполлона из фракийского города Исмара, подарившего Одиссею вино необычайного вкуса и крепости. Как обладатель столь чудесного напитка, Марон в последующем развитии мифа был сделан внуком или непосредственно сыном Диониса."],"k8":["Ст. 163. …. к черту всех хозяев.","Здесь, как и в ст. 339, 529, модернизм переводчика. Античность ничего не знала о «чертях», составляющих атрибут христианской религии. Ср. после ст. 621 слова «Господи, Господи», тоже вставленные Анненским."],"k9":["Ст. 273. Радамант","брат критского царя Миноса, славившийся справедливостью."],"k10":["Ст. 292","Тенар (на юге Пелопоннеса) славился не столько своей гаванью, сколько храмом Посейдона; Суний — мыс на южной оконечности Аттики, где стоял известный храм Посейдона, вблизи находились Лаврийские серебряные рудники; Герест — мыс на крайнем юго-западе о. Евбеи, где также было святилище Посейдона (ср.: Аристофан, «Всадники», ст. 561)."],"k11":["Ст. 304 — 305. …земля Приамова Элладу разоряла…","В словах Одиссея зрители Еврипида находили, конечно, намек на греко-персидскую войну первой половины V в."],"k12":["Ст. 487","Редкий случай, когда в античных рукописях сохраняется ремарка."],"k13":["Ст. 557. Смешалось ли, как следует…","Употребляя вино, греки разбавляли его на две трети водой; для этой цели служили специальные сосуды — кратеры (букв.: «смесители»)."],"k14":["Ст. 620. …для милого, плющом венчанного…","для Диониса."],"k15":["Ст. 624. Козлята (в оригинале «звери»).","По происхождению сатиры являются козлоподобными демонами плодородия, и в их костюме отчасти сохранялось воспоминание о их прошлом."],"k16":["Ст. 654. Мы смелы, как карийцы…","неточный перевод греческой поговорки «рисковать карийцами», т. е. делать опасное дело чужими руками. Храбрые малоазийские карийцы часто служили наемниками в греческих войсках."],"k17":["Ст. 664. Пеан","культовый гимн в честь Аполлона. Здесь употреблено иронически."],"k18":["Ст. 678","Разговорный синтаксис этого стиха исправлен Ф. Зелинским: «Вино — соперник лютый, с ним не шутка»."],"k19":["Ст. 698 — 700. …пророк… судил носиться долго по пучинам…","По Гомеру, долгие скитания не были предназначены Одиссею, а явились результатом гнева Посейдона, преследовавшего его своей местью за ослепление Полифема."]},"mainEnd":1291,"c":[{"id":"odissey","name":"Одиссей","role":"Царь Итаки","intro":"Хитроумный герой, попавший в пещеру Киклопа.","arc":"Сатировская драма пересказывает IX песнь «Одиссеи» в комическом ключе. Одиссей сохраняет свою хитрость и красноречие; в разговоре с Киклопом он говорит о законах гостеприимства, а потом мстит людоеду, опоив его и ослепив.","st":[{"i":314,"p":24,"l":"Действие первое · явление третье","t":"Сделка","d":"Выменивает у Силена овец и сыр на вино.","c":"","k":false},{"i":615,"p":48,"l":"Действие первое · явление шестое","t":"Мольба к Киклопу","d":"Взывает к законам гостеприимства и почтению к богам; Киклоп насмехается.","c":"","k":false},{"i":796,"p":62,"l":"Действие второе · явление седьмое","t":"План мести","d":"Рассказывает, как Киклоп сожрал его спутников, и предлагает сатирам план.","c":"","k":true},{"i":1034,"p":80,"l":"Действие третье · явление восьмое","t":"«Никто»","d":"Поит Киклопа вином и называет себя Никем.","c":"","k":false},{"i":1290,"p":100,"l":"Действие четвертое · явление двенадцатое","t":"Месть","d":"Ослепив Киклопа, открывает своё настоящее имя и уходит к кораблям.","c":"","k":false}]},{"id":"kiklop","name":"Киклоп","role":"Полифем, сын Посейдона","intro":"Одноглазый людоед, презирающий богов и законы.","arc":"Киклоп — софист-материалист: его бог — желудок, а Зевс ему не указ. Пьяный, он становится смешон, ослеплённый — жалок.","st":[{"i":615,"p":48,"l":"Действие первое · явление шестое","t":"Возвращение","d":"Возвращается в пещеру и обвиняет пришельцев в воровстве.","c":"","k":false},{"i":1034,"p":80,"l":"Действие третье · явление восьмое","t":"Пир","d":"Пьянеет и уводит Силена в пещеру.","c":"","k":true},{"i":1290,"p":100,"l":"Действие четвертое · явление двенадцатое","t":"Ослеплён","d":"Выходит слепым, его дразнят сатиры.","c":"","k":false}]},{"id":"silen","name":"Силен","role":"Старый спутник Диониса","intro":"Пьяница, в плену у Киклопа вместе с сатирами.","arc":"Силен — трус и плут: продаёт хозяйское добро за вино и сваливает вину на Одиссея.","st":[{"i":62,"p":5,"l":"Пролог · явление первое","t":"Пролог","d":"Рассказывает, как оказался в плену у Киклопа.","c":"","k":false},{"i":615,"p":48,"l":"Действие первое · явление шестое","t":"Клевета","d":"Обвиняет Одиссея в краже.","c":"","k":true}]}]};
